import { AudioPlayer, createAudioPlayer, setAudioModeAsync } from "expo-audio";

import { storage } from "@/src/utils/storage";

// Original chiptunes generated by /app/scripts/gen_audio.py
const BGM = {
  town: require("../../assets/audio/town.wav"),
  battle: require("../../assets/audio/battle.wav"),
  beach: require("../../assets/audio/beach.wav"),
  bologna: require("../../assets/audio/bologna.wav"),
  osteria: require("../../assets/audio/osteria.wav"),
  terme: require("../../assets/audio/terme.wav"),
  imola: require("../../assets/audio/imola.wav"),
  ferrara: require("../../assets/audio/ferrara.wav"),
  maggiore: require("../../assets/audio/maggiore.wav"),
  altedo: require("../../assets/audio/altedo.wav"),
  // Original 8-bit comic march for Zio DUC's gym.
  duc: require("../../assets/audio/duc.wav"),
};
const SFX = {
  step: require("../../assets/audio/step.wav"),
  select: require("../../assets/audio/select.wav"),
  hit: require("../../assets/audio/hit.wav"),
  catch: require("../../assets/audio/catch.wav"),
  fail: require("../../assets/audio/fail.wav"),
  levelup: require("../../assets/audio/levelup.wav"),
  heal: require("../../assets/audio/heal.wav"),
  encounter: require("../../assets/audio/encounter.wav"),
  evolve: require("../../assets/audio/evolve.wav"),
};
export type BgmName = keyof typeof BGM;
export type SfxName = keyof typeof SFX;

let bgm: AudioPlayer | null = null;
let current: BgmName | null = null;
let muted = false;
let ready = false;
const players: Partial<Record<SfxName, AudioPlayer>> = {};

export async function initAudio() {
  if (ready) return;
  ready = true;
  try {
    await setAudioModeAsync({ playsInSilentMode: true });
  } catch {}
  muted = (await storage.getItem("audio_muted", false)) ?? false;
}

export function playBgm(name: BgmName) {
  try {
    if (current === name && bgm) {
      if (!muted && !bgm.playing) bgm.play();
      return;
    }
    bgm?.pause();
    bgm?.remove();
    current = name;
    bgm = createAudioPlayer(BGM[name]);
    bgm.loop = true;
    bgm.volume = 0.45;
    if (!muted) bgm.play();
  } catch {}
}

export function stopBgm() {
  try {
    bgm?.pause();
  } catch {}
}

export function sfx(name: SfxName, volume = 0.8) {
  if (muted) return;
  try {
    const p = players[name] ?? (players[name] = createAudioPlayer(SFX[name]));
    p.volume = volume;
    p.seekTo(0);
    p.play();
  } catch {}
}

export function isMuted() {
  return muted;
}

export function setMuted(v: boolean) {
  muted = v;
  storage.setItem("audio_muted", v);
  try {
    if (v) bgm?.pause();
    else bgm?.play();
  } catch {}
}
